/** Permanente R5.1-Verhaltensprobe: nur eigene synapse_test/p20_r51-Fixtures. */
import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import {setTimeout as pause} from 'node:timers/promises';
const url=new URL(process.env.DATABASE_URL||'http://invalid');
assert.equal(url.port,'5433');assert.equal(url.pathname,'/synapse_test');
import {oeffneGeschuetzteShellTestDb} from '../../../scripts/lib/test-db-schutz.mjs';
const db=await oeffneGeschuetzteShellTestDb();
const aDb=await oeffneGeschuetzteShellTestDb();
const bDb=await oeffneGeschuetzteShellTestDb();
const adapter=client=>({query:client.query.bind(client),async connect(){return {query:client.query.bind(client),release(){}};}});
const S='p20_r51_'+randomUUID().replaceAll('-',''),P='p20_r51_'+randomUUID();
await db.query('CREATE SCHEMA '+S);
await db.query('SET search_path TO '+S);
await aDb.query('SET search_path TO '+S);
await bDb.query('SET search_path TO '+S);
const pool=adapter(db);
try {
 const {TOOL_CONTAINER_SCHEMA_SQL}=await import('../../core/dist/db/tool-container-schema.js');
 const {WORK_JOBS_SCHEMA_SQL}=await import('../../core/dist/db/work-jobs-schema.js');
 const {TOOL_AKTIVITAET_SCHEMA_SQL}=await import('../../core/dist/db/tool-aktivitaet-schema.js');
 const {validateToolDescriptor,registerToolDescriptor,setToolActivation}=await import('../../core/dist/services/tool-descriptor.js');
 const {erfasseToolAktivitaet}=await import('../../core/dist/services/tool-aktivitaet.js');
 const {ToolLifecycle}=await import('../dist/services/tool-lifecycle.js');
 await db.query(WORK_JOBS_SCHEMA_SQL);await db.query(TOOL_AKTIVITAET_SCHEMA_SQL);
 await db.query(TOOL_CONTAINER_SCHEMA_SQL);await db.query(TOOL_CONTAINER_SCHEMA_SQL);
 await db.query('CREATE TABLE projects(name text,enabled boolean)');
 await db.query('INSERT INTO projects VALUES($1,true)',[P]);
 const d=validateToolDescriptor({tool_id:'fixture',tool:'reverse',capability:'fixture.reverse',image:'fixture:1',digest:'sha256:'+'a'.repeat(64),
  mounts:[],resources:{cpu:1,ram:64,vram:0,gpu:false,pids:32,tmpfs:8,concurrency:2},
  limits:{time_ms:1000,output_bytes:4096,input_bytes:4096},
  lifecycle:{idle_ms:1,activity_lookback_seconds:1,cpu_idle_percent:1,gpu_idle_percent:1,measurement_max_age_ms:1000,start_timeout_ms:1000,max_starts:3,start_window_ms:60000,pause_ms:60000}});
 const actor={role:'koordinator',authenticated:true};
 assert.throws(()=>validateToolDescriptor({...d,digest:'latest'}));
 assert.throws(()=>validateToolDescriptor({...d,mounts:[{role:'project',target:'/project',write:true,project_share:true}]}));
 await assert.rejects(()=>registerToolDescriptor(pool,d,{role:'compute',authenticated:true}));
 await registerToolDescriptor(pool,d,actor);
 await setToolActivation(pool,d.tool_id,null,true,actor);
 await setToolActivation(pool,d.tool_id,P,true,actor);
 let starts=0,stops=0,releases=0,alive=false,fail=false,resolveStop;
 const executor={
  async start(desc,ctx){starts++;assert.equal(desc.network,'none');assert.equal(ctx.project,P);if(fail)throw Error('fixture crash');await pause(5);alive=true;return {id:'fake-'+ctx.generation,coldstart_ms:5};},
  async observe(id){return {running:alive,cpu_percent:0,gpu_percent:null,container_id:id,measured_at:(await db.query('SELECT clock_timestamp() AS t')).rows[0].t.toISOString()};},
  async stop(){stops++;await new Promise(resolve=>{resolveStop=resolve;});alive=false;},
  async command(){return {status:'ok'};}
 };
 const resources={async acquire(){return 'resource-fixture';},async release(){releases++;}};
 const a=new ToolLifecycle({pool:adapter(aDb),executor,resources,maxContainers:1});
 const b=new ToolLifecycle({pool:adapter(bDb),executor,resources,maxContainers:1});
 await a.tick();assert.equal(starts,0,'enabled alone is not activity');
 assert.equal((await a.status('fixture',P)).coldstart_estimate_ms,'unknown');
 const act=()=>erfasseToolAktivitaet({project:P,tool:'reverse',aktion:'inspect',akzeptiert:true,zaehltAlsAktivitaet:true},
  {descriptor:{toolId:'fixture',tool:'reverse',aktivitaetsAktionen:['inspect']},gebundenesProjekt:P,berechtigt:true},pool);
 await act();
 await Promise.all([a.wake('fixture',P),b.wake('fixture',P),a.wake('fixture',P)]);
 assert.equal(starts,1,'PG coldstart singleflight across services');
 assert.equal((await a.status('fixture',P)).coldstart_estimate_ms,5);
 await db.query("UPDATE tool_aktivitaet SET zeit=now()-interval '10 minutes'");
 await db.query("UPDATE tool_containers SET ready_at=now()-interval '10 minutes'");
 const jobId=randomUUID();
 await db.query("INSERT INTO work_jobs(id,kind,capability,project,scope,input_ref,resource_need,priority,idempotency_key,request_hash) VALUES($1,'fixture','fixture.reverse',$2,'fixture',$3,$4,'interaktiv','fixture-job',$5)",
  [jobId,P,{scope:'fixture',id:'input',revision:'1',sha256:'b'.repeat(64)},{cpu:1,ram:16,vram:0,gpu:false},'c'.repeat(64)]);
 await a.tick();assert.equal(stops,0,'open job prevents idle stop beyond X');
 await db.query("UPDATE work_jobs SET state='cancelled' WHERE id=$1",[jobId]);
 const stopping=a.tick();
 for(let n=0;!resolveStop&&n<500;n++)await pause(10);assert(resolveStop,JSON.stringify(await a.status('fixture',P)));
 assert.equal((await a.status('fixture',P)).status,'stopping');
 await act();await b.wake('fixture',P);
 assert.equal(starts,1,'call while stopping is durably queued');
 resolveStop();await stopping;
 assert.equal(releases,1,'resource release only after observed Docker end');
 await a.tick();assert.equal(starts,2,'held activity is not lost');
 await db.query("UPDATE tool_aktivitaet SET zeit=now()-interval '10 minutes'");
 await db.query("UPDATE tool_containers SET ready_at=now()-interval '10 minutes'");
 resolveStop=undefined;
 const stop2=a.tick();for(let n=0;!resolveStop&&n<500;n++)await pause(10);assert(resolveStop,JSON.stringify(await a.status('fixture',P)));resolveStop();await stop2;
 fail=true;await act();
 await assert.rejects(()=>a.wake('fixture',P),/fixture crash|container_gesperrt/);
 await a.wake('fixture',P).catch(()=>{});
 assert.equal((await a.status('fixture',P)).status,'blocked','crash loop blocks starts');
 console.log('PASS p20_r51: descriptor/auth/DDL/enabled/singleflight/PGjobs/idle/stopping/requeue/coldstart/crashblock');
 a.close();b.close();
} finally {await aDb.end();await bDb.end();await db.query('SET search_path TO public');await db.query('DROP SCHEMA '+S+' CASCADE');await db.end();}

/** R5.2: nur synapse_test, eigener Bereich p20_r52. Golden vor Produktion erfasst. */
import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
const url=new URL(process.env.DATABASE_URL||'http://invalid');
assert.equal(url.port,'5433');assert.equal(url.pathname,'/synapse_test');
const {getPool,closePool}=await import('../dist/db/client.js');
const {logToolCall,queryToolCalls}=await import('../dist/services/tool-call-log.js');
const pool=getPool(),P='p20_r52_'+randomUUID(),S='p20_r52_'+randomUUID().replaceAll('-','');
const normal=rows=>rows.map(({id,ts,...row})=>row);
try {
 await logToolCall({project:P,agentId:'sol-7-test',tool:'reverse',action:'inspect',argsPreview:'{"fixture":true}',ok:true,durationMs:7,result:'{"success":true}'});
 const base={project:P,agent_id:'sol-7-test',source:null,tool_name:'reverse',action:'inspect',args_preview:'{"fixture":true}',ok:true,error:null,duration_ms:7,is_mutation:false};
 assert.deepEqual(normal(await queryToolCalls({project:P})),[base]);
 assert.deepEqual(normal(await queryToolCalls({project:P,detail:'summary'})),[{...base,result_bytes:16,result_truncated:false,result_preview:'{"success":true}'}]);
 assert.deepEqual(normal(await queryToolCalls({project:P,detail:'full'})),[{...base,result_bytes:16,result_truncated:false,result:'{"success":true}'}]);
 assert.deepEqual(await queryToolCalls({project:P,status:'error'}),[]);
 console.log('GOLDEN tool_calls meta/summary/full/filter unchanged');
 if(process.argv.includes('--golden'))process.exitCode=0;
 else {
  const m=await import('../dist/services/tool-aktivitaet.js');
  const {TOOL_AKTIVITAET_SCHEMA_SQL}=await import('../dist/db/tool-aktivitaet-schema.js');
  const c=await pool.connect();
  try {
   await c.query('CREATE SCHEMA '+S);
   await c.query('SET search_path TO '+S);
   await c.query(TOOL_AKTIVITAET_SCHEMA_SQL);await c.query(TOOL_AKTIVITAET_SCHEMA_SQL);
   const descriptor={toolId:'reverse-fixture',tool:'reverse',aktivitaetsAktionen:['inspect','status','heartbeat']};
   const ctx={descriptor,gebundenesProjekt:P,berechtigt:true};
   const entry={project:P,tool:'reverse',aktion:'inspect',agentId:'sol-7-test',containerId:'container-fixture',jobId:'job-fixture',akzeptiert:true,zaehltAlsAktivitaet:true};
   const accepted=await m.erfasseToolAktivitaet(entry,ctx,c);
   assert.equal(accepted.zaehlt_als_aktivitaet,true);
   assert(accepted.zeit instanceof Date);
   for(const [patch,context] of [
    [{akzeptiert:false},ctx],[{}, {...ctx,berechtigt:false}],[{project:'foreign'},ctx],
    [{tool:'admin'},ctx],[{aktion:'status'},ctx],[{aktion:'heartbeat'},ctx],
    [{aktion:'unknown'},ctx],[{zaehltAlsAktivitaet:false},ctx]
   ]) assert.equal((await m.erfasseToolAktivitaet({...entry,...patch},context,c)).zaehlt_als_aktivitaet,false);
   const query={project:P,toolId:descriptor.toolId,tool:'reverse',fensterSekunden:60};
   assert.deepEqual((await m.letzteToolAktivitaet(query,c)).map(x=>x.id),[accepted.id]);
   assert.deepEqual(await m.letzteToolAktivitaet({...query,project:'foreign'},c),[]);
   assert.deepEqual(await m.letzteToolAktivitaet({...query,containerId:'foreign'},c),[]);
   assert.deepEqual(await m.letzteToolAktivitaet({...query,toolId:'foreign'},c),[]);
   // Mehrere gleichzeitige Calls: numerische Sequenz gewinnt auch bei gleicher PG-Zeit.
   await c.query('BEGIN');
   const tie1=await m.erfasseToolAktivitaet(entry,ctx,c);
   const tie2=await m.erfasseToolAktivitaet(entry,ctx,c);
   assert.equal(+tie1.zeit,+tie2.zeit);
   assert.deepEqual((await m.letzteToolAktivitaet(query,c)).map(x=>x.id),[tie2.id]);
   await c.query('ROLLBACK');
   // Client-Zeit ist kein Eingabevertrag und kann die PG-Zeit nicht manipulieren.
   const pgBefore=(await c.query('SELECT clock_timestamp() AS t')).rows[0].t;
   const timed=await m.erfasseToolAktivitaet({...entry,zeit:'1900-01-01'},ctx,c);
   const pgAfter=(await c.query('SELECT clock_timestamp() AS t')).rows[0].t;
   assert(+timed.zeit>=+pgBefore && +timed.zeit<=+pgAfter);
   await c.query('DELETE FROM tool_aktivitaet WHERE id=$1',[timed.id]);
   await assert.rejects(()=>c.query("INSERT INTO tool_aktivitaet(projekt,tool,aktion,tool_id,akzeptiert,berechtigt,projekt_gebunden,zaehlt_als_aktivitaet) VALUES ('fixture','reverse','inspect','reverse-fixture',false,true,true,true)"),e=>e.code==='23514');
   await assert.rejects(()=>m.letzteToolAktivitaet(query,{query:async()=>{throw Error('fixture read unavailable');}}),/fixture read unavailable/);
   await c.query("UPDATE tool_aktivitaet SET zeit=now()-interval '2 minutes' WHERE id=$1",[accepted.id]);
   assert.deepEqual(await m.letzteToolAktivitaet(query,c),[]);
   assert.equal((await m.letzteToolAktivitaet({...query,fensterSekunden:180},c)).length,1);
   await assert.rejects(()=>m.letzteToolAktivitaet({...query,fensterSekunden:0},c));
   await assert.rejects(()=>m.letzteToolAktivitaet({...query,fensterSekunden:Infinity},c));
   await assert.rejects(()=>m.letzteToolAktivitaet({...query,fensterSekunden:91*86400},c));
   await c.query('BEGIN');
   const rolled=await m.erfasseToolAktivitaet(entry,ctx,c);
   await c.query('ROLLBACK');
   assert.equal((await c.query('SELECT count(*)::int AS n FROM tool_aktivitaet WHERE id=$1',[rolled.id])).rows[0].n,0);
   await assert.rejects(()=>m.erfasseToolAktivitaet(entry,ctx,{query:async()=>{throw Error('fixture db unavailable');}}),/fixture db unavailable/);
   await c.query("UPDATE tool_aktivitaet SET zeit=now()-interval '100 days'");
   assert.equal(await m.bereinigeToolAktivitaet(c),9);
   assert.deepEqual(await m.letzteToolAktivitaet(query,c),[]);
   process.env.SYNAPSE_TOOL_AKTIVITAET_RETENTION_DAYS='2';
   assert.equal(m.toolAktivitaetRetentionTage(),2);
   await assert.rejects(()=>m.letzteToolAktivitaet({...query,fensterSekunden:3*86400},c));
   process.env.SYNAPSE_TOOL_AKTIVITAET_RETENTION_DAYS='invalid';
   assert.throws(()=>m.toolAktivitaetRetentionTage());
   delete process.env.SYNAPSE_TOOL_AKTIVITAET_RETENTION_DAYS;
   console.log('PASS p20_r52 acceptance, binding, polls, descriptor, PG window, durability, transaction, retention, idempotent DDL');
  } finally {await c.query('SET search_path TO public');await c.query('DROP SCHEMA IF EXISTS '+S+' CASCADE');c.release();}
 }
} finally {await pool.query('DELETE FROM tool_calls WHERE project=$1',[P]);await closePool();}

/** P6-T48: Golden offener Plan, planlose Hinweise/Schatten und alte zielose Waits; nur synapse_test:5433. */
import assert from 'node:assert/strict';
import {randomUUID,createHash} from 'node:crypto';
import {readFileSync} from 'node:fs';
const u=new URL(process.env.DATABASE_URL||'http://ungueltig');
assert.equal(u.port,'5433'); assert.equal(u.pathname,'/synapse_test');
process.env.SYNAPSE_PLAN_PRUEFUNG='0'; process.env.QDRANT_URL='http://127.0.0.1:9';
const dist=new URL(process.env.P6_T48_DIST ? 'file://'+process.env.P6_T48_DIST.replace(/\/$/,'')+'/' : '../dist/',import.meta.url);
const load=rel=>import(new URL(rel,dist));
const batch=await load('services/file-batch.js');
const res=await load('services/file-reservations.js');
const ci=await load('services/code-intel.js');
const {mitCodeIntelSchatten}=await load('services/code-intel-schatten.js');
const {getPool}=await load('db/client.js'); const pool=getPool();
assert.equal((await pool.query('SELECT current_database() AS db')).rows[0].db,'synapse_test');
const project='p6_t48_'+randomUUID(), owner='sol-9-t48-owner', writer='sol-9-t48-writer';
const names=new Map(), hash=s=>createHash('sha256').update(s).digest('hex');
const normal=v=>JSON.parse(JSON.stringify(v,(k,x)=>{
 if(['schatten_parse_ms','duration_ms','dauer_ms','ms','gewartet_ms'].includes(k))return undefined;
 if(['expires_at','reserved_at','reserved_since','created_at','updated_at','seit'].includes(k))return '<zeit>';
 if(k==='wait_token')return '<wait>';
 if(typeof x!=='string')return x;
 let out=x.replaceAll(project,'<project>');
 for(const [id,name]of names)out=out.replaceAll(id,name);
 return out;
}));
const op=(file,search,replace)=>({action:'search_replace',file_path:file,search,replace});
const seed=async file=>{
 const content='export function probe(){ return 1; }\n';
 await pool.query('INSERT INTO code_files(id,project,file_path,file_name,file_type,file_size,content,content_hash) VALUES($1,$2,$3,$4,$5,$6,$7,$8)',
 [randomUUID(),project,file,file.split('/').at(-1),'ts',Buffer.byteLength(content),content,hash(content)]);
};
const run=(action,a)=>mitCodeIntelSchatten(action,{project,...a},async()=>{
 if(action==='file'){const f=await ci.getFileContent(project,a.file_path);return {success:!!f,...f,project};}
 if(action==='tree')return {success:true,tree:await ci.getProjectTree(project,a),project};
 if(action==='functions'){const functions=await ci.getFunctions(project,a.file_path);return {success:true,functions,project};}
 const symbols=await ci.getSymbols(project,a.symbol_type,a.file_path,undefined,100);return {success:true,symbols,project};
});
try {
 await pool.query('INSERT INTO projects(name,hostname,path) VALUES($1,$2,$3)',[project,'p6-t48-test','/virtual/p6-t48']);
 for(const file of ['src/golden.ts','src/free.ts','src/legacy.ts','src/expired.ts','src/multi-a.ts','src/multi-b.ts'])await seed(file);
 // Altumfang: vorhandener Ownerplan => exakt dieselbe Antwort, Waitbindung und contribution.
 await res.addFileReservations({project,agentId:owner,filePaths:['src/golden.ts']});
 const p=await batch.planBatch({project,agent_id:owner,ops:[op('src/golden.ts','return 1','return 2')]}); names.set(p.plan_id,'<owner-plan>');
 const w=await batch.planBatch({project,agent_id:writer,ops:[op('src/golden.ts','probe','goldenProbe')]}); names.set(w.plan_id,'<carrier>');
 const contribution=await batch.addCoeditContribution({project,plan_id:p.plan_id,wait_token:w.coedit_waits[0].wait_token,agent_id:writer,ops:[op('src/golden.ts','probe','goldenProbe')]});
 const golden=normal({plan:p,wait:w,contribution});
 if(process.argv.includes('--capture'))console.log('GOLDEN_JSON='+JSON.stringify(golden));
 else assert.deepEqual(golden,JSON.parse(readFileSync(new URL('./fixtures/file-reservation-planless-p6-t48.golden.json',import.meta.url),'utf8')));
 if(!process.argv.includes('--capture')&&!process.argv.includes('--golden')){
  // Kein Plan: Absicht sichtbar, Bestand unverändert, Schreiben ohne Wait.
  await res.addFileReservations({project,agentId:owner,filePaths:['src/free.ts','lib/new.ts']});
  if(!process.argv.includes('--planlos')) {
  for(const action of ['file','functions','symbols']){
   const out=await run(action,{file_path:'src/free.ts',symbol_type:'function',schatten:'alle'});
   assert.equal(out.reservierungen?.[0]?.reserviert_von,owner,action+': Reservierung sichtbar');
   assert.equal(out.reservierungen[0].file_path,'src/free.ts');
   assert.ok(out.reservierungen[0].seit&&out.reservierungen[0].expires_at);
   assert.ok(Object.hasOwn(out.reservierungen[0],'task_id'));
  }
  const tree=await run('tree',{path:'lib',show_ghosts:true});
  assert.ok(tree.reservierungen?.some(r=>r.file_path==='lib/new.ts'));
  assert.match(tree.tree,/new.ts/);assert.match(tree.tree,/Reservierungen ohne Plan/);
  const scoped=await run('file',{file_path:'src/free.ts',schatten:p.plan_id});
  assert.ok(scoped.reservierungen?.some(r=>r.file_path==='src/free.ts'));
  const plain=await run('file',{file_path:'src/free.ts'});
  assert.ok(!Object.hasOwn(plain,'reservierungen'),'ohne Schalter unverändert');
  }
  const planned=await batch.planBatch({project,agent_id:writer,ops:[op('src/free.ts','return 1','return 3')]});
  assert.equal(planned.total_ops,1);assert.ok(!planned.coedit_waits?.length);assert.ok(!planned.deferred_ops);
  assert.equal(planned.reservation_hint.files[0].reserviert_von,owner);
  const c=await batch.commitBatch({plan_id:planned.plan_id,agent_id:writer});assert.equal(c.success,true);
  assert.match((await ci.getFileContent(project,'src/free.ts')).content,/return 3/);
  // Gegenprobe: freigegebene/abgelaufene/fremde Reservierungen werden nicht gezeigt.
  await pool.query("INSERT INTO file_reservations(project,agent_id,file_path,content_hash_at_reservation,expires_at) VALUES($1,$2,'src/expired.ts',$3,NOW()-INTERVAL '1 hour')",[project,owner,hash('')]);
  assert.ok(!(await run('file',{file_path:'src/expired.ts',schatten:'alle'})).reservierungen);
  await res.releaseFileReservations({project,agentId:owner,filePaths:['lib/new.ts']});
  assert.ok(!(await run('tree',{path:'lib',show_ghosts:true})).reservierungen);
  // Stresstest-Muster: zwei Reservierungen ohne Plan, genau ein sofortiger Writerplan;
  // späterer Reservierender landet additiv in diesem bestehenden Ziel, kein Parallelplan.
  await res.addFileReservations({project,agentId:owner,filePaths:['src/multi-a.ts','src/multi-b.ts']});
  const multi=await batch.planBatch({project,agent_id:writer,ops:[
   op('src/multi-a.ts','return 1','return 5'),op('src/multi-b.ts','return 1','return 6')]});
  assert.equal(multi.total_ops,2);assert.ok(!multi.coedit_waits?.length);
  assert.equal(multi.reservation_hint.files.length,2);
  const followerOps=[op('src/multi-a.ts','probe','laterA'),op('src/multi-b.ts','probe','laterB')];
  const follower=await batch.planBatch({project,agent_id:owner,ops:followerOps});
  assert.equal(follower.total_ops,0);assert.equal(follower.coedit_waits.length,1);
  assert.equal(follower.coedit_waits[0].target_plan_id,multi.plan_id);
  const followAdd=await batch.addCoeditContribution({project,plan_id:multi.plan_id,
   wait_token:follower.coedit_waits[0].wait_token,agent_id:owner,ops:followerOps});
  assert.equal(followAdd.success,true);assert.equal(followAdd.total_plan_ops,4);
  await batch.markCoeditReady({project,plan_id:multi.plan_id,agent_id:owner});
  assert.equal((await batch.commitBatch({plan_id:multi.plan_id,agent_id:writer})).success,true);
  assert.match((await ci.getFileContent(project,'src/multi-a.ts')).content,/laterA.*return 5/);
  assert.match((await ci.getFileContent(project,'src/multi-b.ts')).content,/laterB.*return 6/);
  assert.equal((await pool.query('SELECT status FROM file_batch_plans WHERE id=$1',[follower.plan_id])).rows[0].status,'cancelled');
  // Alt-Wait synthetisch nachstellen: spätere Ownerplanung bindet ihn, Inhalte bleiben erhalten.
  await res.addFileReservations({project,agentId:owner,filePaths:['src/legacy.ts']});
  const carrier=(await pool.query("INSERT INTO file_batch_plans(project,owner_agent_id,ops,expected_hashes,previews) VALUES($1,$2,'[]','{}','[]') RETURNING id::text",[project,writer])).rows[0].id;
  const deferred=[op('src/legacy.ts','probe','legacyProbe')];
  const wait=(await pool.query("INSERT INTO file_batch_waits(source_plan_id,project,waiting_agent,primary_agent,shared_files,deferred_ops,deferred_op_indexes,expires_at) VALUES($1,$2,$3,$4,$5,$6::jsonb,$7,NOW()+INTERVAL '1 minute') RETURNING wait_token::text",
   [carrier,project,writer,owner,['src/legacy.ts'],JSON.stringify(deferred),[0]])).rows[0].wait_token;
  const legacy=await batch.planBatch({project,agent_id:owner,ops:[op('src/legacy.ts','return 1','return 4')]});
  const bound=(await pool.query('SELECT primary_plan_id::text,deferred_ops FROM file_batch_waits WHERE wait_token=$1',[wait])).rows[0];
  assert.equal(bound.primary_plan_id,legacy.plan_id);assert.deepEqual(bound.deferred_ops,deferred);
  const status=await batch.getSharedPlanStatus({project,wait_token:wait,agent_id:writer});
  assert.equal(status.target_plan_id,legacy.plan_id);
  const added=await batch.addCoeditContribution({project,plan_id:legacy.plan_id,wait_token:wait,agent_id:writer,ops:deferred});
  assert.equal(added.success,true);
  await batch.markCoeditReady({project,plan_id:legacy.plan_id,agent_id:writer});
